UPDATE characters SET description = 'ベニマルはリムル=テンペストに名前をもらった3番目の部下モンスターグループの一員である。元々は鬼族だったが、仕えることに迷いがあり一時的なつもりだったが、名前をもらった後は鬼人へと進化し、すぐにリムルの最強の部下となり、永遠に仕えることを決めた。彼はジュラ・テンペスト連邦の首都であるリムル市に住んでいる。その後すぐに総司令官となり、テンペスト軍の統率権を直接に握ることになった。リムルが真なる魔王へと昇り詰めると、ベニマルは鬼人から美しき鬼へと進化した。', tags = ARRAY['赤髪','長身','筋肉質','角','クール','真面目','人外','魔王']::text[], voice_actor = '古川慎' WHERE character_id = 'CH012198'; -- ベニマル
UPDATE characters SET description = 'ヴェルドラ＝テンペストは、四大真竜の最年少である。彼は契約によってリムルと繋がっており、各地で暴れ回ることで知られていた。リムルを命名したのは彼であり、リムルは彼に姓を与えた。同じ姓を共有しているため、技術的にはリムルはヴェルドラ＝テンペストの義兄弟として分類できる。

祝福：嵐竜の恵み、魔王の盟友
災害等級：破滅級', tags = ARRAY['長身','お姉さん','人外','魔王','異世界転生']::text[], voice_actor = '前野智昭' WHERE character_id = 'CH012200'; -- ヴェルドラ＝テンペスト
UPDATE characters SET description = 'ミリム・ナーヴァは最古の魔王の一人であり、最強クラスの実力者だ。竜人族に属する彼女のあだ名「破壊者」は伊達ではない。決して敵に回してはいけない魔王である。', tags = ARRAY['ピンク髪','ロングヘア','角','翼','長身','お姉さん','ドレス','クール','魔王','人外']::text[], voice_actor = '日高里菜' WHERE character_id = 'CH012201'; -- ミリム・ナーヴァ
UPDATE characters SET description = 'シオンは、リムルの最初の部下であり、彼の専属秘書として身の回りの世話を担当している「戦鬼」である。また、よみがえりの指導者でもあり、リムルの最強の戦力の一人であり、彼女に会った多くの魔王たちから欲しがられている存在である。', tags = ARRAY['銀髪','ロングヘア','赤目','角','長身','巨乳','お姉さん','クール','真面目','ヒロイン','人外','魔王']::text[], voice_actor = '市道真央' WHERE character_id = 'CH012203'; -- シオン